import React, { useState, useEffect } from "react";
import "./Dashboard.css";

function Dashboard() {
  const [file, setFile] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [type, setType] = useState("");
  const [darkMode, setDarkMode] = useState(false);
  const [activeTab, setActiveTab] = useState("overview");
  const [loading, setLoading] = useState(false);

  const [profile, setProfile] = useState({
    name: "User",
    email: "user@email.com"
  });

  const [alerts, setAlerts] = useState([]);
  const [insights, setInsights] = useState([]);

  useEffect(() => {
    const saved = JSON.parse(localStorage.getItem("profile"));
    if (saved) setProfile(saved);
  }, []);

  // ✅ CATEGORY NORMALIZATION
  const normalizeCategory = (cat = "", desc = "") => {
    const text = (cat + " " + desc).toLowerCase();

    if (text.includes("food") || text.includes("grocery"))
      return "food & groceries";

    if (
      text.includes("bill") ||
      text.includes("recharge") ||
      text.includes("jio") ||
      text.includes("airtel") ||
      text.includes("electric") ||
      text.includes("water") ||
      text.includes("gas") ||
      text.includes("internet") ||
      text.includes("mobile")
    )
      return "bills";

    if (text.includes("shop") || text.includes("amazon") || text.includes("myntra"))
      return "shopping";

    if (text.includes("health"))
      return "health";

    if (text.includes("uber") || text.includes("ola") || text.includes("transport"))
      return "transport";

    return "other / miscellaneous";
  };

  // ✅ SOURCE DETECTION
  const detectSource = (txns) => {
    if (!txns.length) return "Not uploaded";

    const text = txns.map(t => (t.description || "").toLowerCase()).join(" ");

    if (text.includes("upi")) return "GPay";
    if (text.includes("hdfc")) return "HDFC Bank";

    return "Bank Statement";
  };

  // ✅ ALERT SYSTEM (returns result ALSO)
  const checkAlerts = (txns) => {
    const user = JSON.parse(localStorage.getItem("user"));
    if (!user) return [];

    const rawLimits =
      JSON.parse(localStorage.getItem(`limits_${user.email}`)) || {};

    let normalizedLimits = {};
    Object.keys(rawLimits).forEach(key => {
      const normalizedKey = normalizeCategory(key);
      normalizedLimits[normalizedKey] = Number(rawLimits[key]);
    });

    let totals = {};
    txns.forEach(t => {
      const cat = normalizeCategory(t.category, t.description);
      totals[cat] = (totals[cat] || 0) + Number(t.amount || 0);
    });

    let result = [];

    Object.keys(normalizedLimits).forEach(cat => {
      const spent = totals[cat] || 0;
      const limit = normalizedLimits[cat];

      result.push({
        category: cat,
        spent,
        limit,
        exceeded: spent > limit
      });
    });

    setAlerts(result);
    return result; // ✅ IMPORTANT
  };

  // ✅ AI INSIGHTS (NOW STABLE)
  const generateInsights = (txns, alertsData) => {
    if (!txns.length) return;

    let totals = {};
    let smallTxns = 0;

    txns.forEach(t => {
      const cat = normalizeCategory(t.category, t.description);
      const amount = Number(t.amount || 0);

      totals[cat] = (totals[cat] || 0) + amount;

      if (amount < 200) smallTxns++;
    });

    const totalSpend = Object.values(totals).reduce((a, b) => a + b, 0);

    const sorted = Object.entries(totals).sort((a, b) => b[1] - a[1]);

    let insightsList = [];

    // 🔹 Top category
    if (sorted.length > 0) {
      const [topCat, topVal] = sorted[0];
      const percent = ((topVal / totalSpend) * 100).toFixed(1);

      insightsList.push(`💸 ${percent}% of your spending is on ${topCat}`);
    }

    // 🔹 Budget alerts
    alertsData.forEach(a => {
      if (a.exceeded) {
        insightsList.push(`🚨 You exceeded budget in ${a.category}`);
      } else if (a.limit > 0 && a.spent / a.limit > 0.8) {
        insightsList.push(`⚠️ Near limit in ${a.category}`);
      }
    });

    // 🔹 Behavior pattern
    if (smallTxns > txns.length * 0.5) {
      insightsList.push("📉 Frequent small spends detected (impulse pattern)");
    }

    // 🔹 Spread
    if (sorted.length <= 3) {
      insightsList.push("✅ Spending is well controlled");
    } else {
      insightsList.push("📊 Spending spread across many categories");
    }

    // 🔹 Smart suggestion
    if (sorted.length > 0) {
      insightsList.push(`💡 Reduce ${sorted[0][0]} to increase savings`);
    }

    setInsights(insightsList);
  };

  // ✅ UPLOAD HANDLER
  const handleUpload = async () => {
    if (!file) return alert("Select file");

    setLoading(true);

    const formData = new FormData();
    formData.append("file", file);

    const res = await fetch("http://localhost:8000/upload-statement/", {
      method: "POST",
      body: formData
    });

    const data = await res.json();
    const txns = data.transactions || [];

    setTransactions(txns);
    setType(detectSource(txns));

    const alertsData = checkAlerts(txns); // ✅ get alerts immediately
    generateInsights(txns, alertsData);   // ✅ pass alerts safely

    const history = JSON.parse(localStorage.getItem("history")) || [];

    history.unshift({
      date: new Date().toLocaleString(),
      type: detectSource(txns),
      count: txns.length,
      transactions: txns
    });

    localStorage.setItem("history", JSON.stringify(history));

    setLoading(false);
  };

  const deleteHistory = (i) => {
    const history = JSON.parse(localStorage.getItem("history")) || [];
    history.splice(i, 1);
    localStorage.setItem("history", JSON.stringify(history));
    setActiveTab("history");
  };

  return (
    <div className={`dashboard-main ${darkMode ? "dark" : ""}`}>
      <div className="container">

        {/* NAVBAR */}
        <div className="navbar">
          <div>
            <div className="logo">FinSight</div>
            <div style={{ fontSize: "13px", color: "#6b7280" }}>
              Personal Expense Intelligence
            </div>
          </div>

          <div className="nav-actions">
            <div className="tabs">
              <span
                className={`tab ${activeTab === "overview" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("overview")}
              >
                Overview
              </span>

              <span
                className={`tab ${activeTab === "history" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("history")}
              >
                History
              </span>
            </div>

            <div className="profile-avatar">
              {profile.name.charAt(0).toUpperCase()}
            </div>

            <div
              onClick={() => setDarkMode(!darkMode)}
              className="theme-toggle"
            ></div>
          </div>
        </div>

        {/* HERO */}
        <div className="hero">
          <h1>
            Welcome, <span style={{ color: "#4f6df5" }}>{profile.name}</span>
          </h1>
        </div>

        {/* OVERVIEW */}
        {activeTab === "overview" && (
          <>
            {/* KPI */}
            <div className="kpi-grid">
              <div className="kpi-card">
                <h4>Statement Source</h4>
                <p>{type || "Not uploaded"}</p>
              </div>

              <div className="kpi-card">
                <h4>Total Transactions</h4>
                <p>{transactions.length}</p>
              </div>

              <div className="kpi-card">
                <h4>Status</h4>
                <p>{transactions.length ? "Processed" : "Waiting"}</p>
              </div>
            </div>

            {/* TOP SECTION */}
            <div className="top-section">
              <div className="card upload-card">
                <h3>Upload Statement</h3>

                <div className="upload-row">
                  <input
                    type="file"
                    accept=".pdf"
                    onChange={(e) => setFile(e.target.files[0])}
                  />

                  <button onClick={handleUpload}>
                    {loading ? "Processing..." : "Analyze Statement"}
                  </button>
                </div>
              </div>

              <div className="card summary-card">
                <h3>Insights Summary</h3>
                {insights.length > 0
                  ? insights.map((i, idx) => <p key={idx}>{i}</p>)
                  : <p>Upload a statement</p>}
              </div>
            </div>

            {/* ALERTS UI */}
            {alerts.length > 0 && (
              <div className="card table-card">
                <h3>Budget Alerts</h3>

                {alerts.map((a, i) => {
                  const percent = a.limit ? (a.spent / a.limit) * 100 : 0;

                  return (
                    <div key={i} style={{ marginBottom: "16px" }}>
                      <div style={{
                        display: "flex",
                        justifyContent: "space-between"
                      }}>
                        <span>{a.category}</span>
                        <span>
                          ₹{a.spent} / ₹{a.limit} {a.exceeded ? "🚨" : "✅"}
                        </span>
                      </div>

                      <div style={{
                        height: "6px",
                        background: "#e5e7eb",
                        borderRadius: "6px",
                        marginTop: "4px"
                      }}>
                        <div style={{
                          width: `${Math.min(percent, 100)}%`,
                          height: "100%",
                          background: a.exceeded ? "#ef4444" : "#22c55e"
                        }} />
                      </div>
                    </div>
                  );
                })}
              </div>
            )}

            {/* TABLE */}
            {transactions.length > 0 && (
              <div className="card table-card">
                <h3>Transaction Ledger</h3>

                <div style={{ maxHeight: "400px", overflow: "auto" }}>
                  <table style={{ width: "100%" }}>
                    <thead>
                      <tr>
                        <th>Date</th>
                        <th>Type</th>
                        <th>Description</th>
                        <th>Category</th>
                        <th>Need/Want</th>
                        <th>Amount</th>
                      </tr>
                    </thead>

                    <tbody>
                      {transactions.map((txn, i) => (
                        <tr key={i}>
                          <td>{txn.date}</td>
                          <td>{txn.type}</td>
                          <td>{txn.description}</td>
                          <td>{txn.category || "-"}</td>
                          <td>{txn.need_or_want || "-"}</td>
                          <td>₹{txn.amount}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </>
        )}

        {/* HISTORY */}
        {activeTab === "history" && (
          <div className="card table-card">
            <h3>History</h3>

            <div style={{ maxHeight: "400px", overflow: "auto" }}>
              <table style={{ width: "100%" }}>
                <tbody>
                  {(JSON.parse(localStorage.getItem("history")) || []).map((h, i) => (
                    <tr key={i}>
                      <td>{h.date}</td>
                      <td>{h.type}</td>
                      <td>{h.count}</td>
                      <td>
                        <button onClick={() => {
                          setTransactions(h.transactions);
                          setType(h.type);
                          setActiveTab("overview");
                        }}>
                          View
                        </button>

                        <button onClick={() => deleteHistory(i)}>
                          Delete
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

      </div>
    </div>
  );
}

export default Dashboard;
